WITH homes AS (SELECT p.city,p.release_id,r.retrieved_at,a.record FROM japan_area_publications p JOIN japan_area_releases r ON r.id=p.release_id JOIN japan_area_records a ON a.release_id=p.release_id WHERE p.year=2026 AND p.quarter=1 AND r.state='published' AND a.record->>'type'='Pre-owned Condominiums, etc.'), groups AS (SELECT cap,city,release_id,max(retrieved_at)::text retrieved_at,floor((record->>'areaSqm')::numeric/20)*20 area_band,count(*)::int n,min((record->>'areaSqm')::numeric) area_min,max((record->>'areaSqm')::numeric) area_max,min((record->>'price')::numeric) price_min,max((record->>'price')::numeric) price_max FROM homes CROSS JOIN (SELECT unnest(ARRAY[30000000,50000000,100000000])::numeric cap) caps WHERE (record->>'price')::numeric BETWEEN cap*.8 AND cap AND (record->>'areaSqm')::numeric>0 GROUP BY cap,city,release_id,floor((record->>'areaSqm')::numeric/20)*20 HAVING count(*)>=5), ranked AS (SELECT *,row_number() OVER(PARTITION BY cap,city ORDER BY n DESC,area_band) ward_rank FROM groups), finalists AS (SELECT *,row_number() OVER(PARTITION BY cap ORDER BY n DESC,city) slot FROM ranked WHERE ward_rank=1) SELECT * FROM finalists WHERE slot<=5 ORDER BY cap,slot
